mapper.select:
select id,cust_num as custNum,dx_type as dxType,`type`
from b_phone_sale_extend_info
where api_code = #{apiCode}
and cust_num in

    #{custNum}

and p_status = 2
and transform_type = #{transferType}

     and applet_date >= #{startDate} 


     and applet_date <= #{endDate}

select b.cust_num as custNum,b.dx_type as dxType,b.`type`,b.applet_date from
(
select cust_num,max(applet_date) as applet_date
from b_phone_sale_extend_info
where api_code = #{apiCode}
  and cust_num in

    #{custNum}

and p_status = 2
and transform_type = #{transferType}
group by cust_num
) as a
left join b_phone_sale_extend_info b on a.cust_num = b.cust_num and a.applet_date = b.applet_date
where b.api_code = #{apiCode} and b.p_status = 2 and b.transform_type = #{transferType}

select b.cust_num as custNum,b.dx_type as dxType,b.`type`,b.applet_date from ( select cust_num,max(applet_date) as applet_date from b_phone_sale_extend_info where api_code = #{apiCode} and p_status = 2 and transform_type = #{transferType} and
(cust_num = #{custNumAndApplet.custNum} and applet_date < #{custNumAndApplet.appletDate})
group by cust_num ) as a left join b_phone_sale_extend_info b on a.cust_num = b.cust_num and a.applet_date = b.applet_date where b.api_code = #{apiCode} and b.p_status = 2 and b.transform_type = #{transferType}

select cust_num
from b_phone_sale_extend_info
where api_code = #{apiCode}
and cust_num in

    #{custNum}

and p_status = 2
and transform_type = #{transferType}
 and applet_date >= #{startDate} 
 and applet_date <= #{endDate}

select count(*)
from b_phone_sale_extend_info
where dx_type = #{dxType}
and applet_date = #{date}
and phone = #{phone}

select * from b_phone_sale_extend_info
where api_code =#{apiCode}
 AND push_dx_time >= #{startDate} and push_dx_time <= #{endDate} 
order by push_dx_time desc,id desc limit #{limitStart},2000;
